import pandas as pd

def find_persistent_users(user_actions: pd.DataFrame) -> pd.DataFrame:
    if user_actions.empty:
        return pd.DataFrame({'user_id': []})
    df = user_actions[['user_id', 'action_date']].drop_duplicates()
    df['action_date'] = pd.to_datetime(df['action_date'])
    df = df.sort_values(['user_id', 'action_date'])
    df['day_diff'] = (df['action_date'] - pd.to_datetime('2000-01-01')).dt.days
    df['rn'] = df.groupby('user_id').cumcount()
    df['grp'] = df['day_diff'] - df['rn']
    streak = df.groupby(['user_id', 'grp']).size().reset_index(name='streak_days')
    qualifying = streak[streak['streak_days'] >= 3]['user_id'].drop_duplicates().sort_values()
    return pd.DataFrame({'user_id': qualifying})
